custom_css:
/* ===========全局=========== */
/* 字体 */
@import url('https://fontsapi.zeoseven.com/488/main/result.css');

body, code, pre, textarea, input, button, select {
  font-family: 'STDongGuanTi', sans-serif !important; 
  font-weight: normal;
  font-size: 16px; /* 基础字体大小 */
}

/* ===========气泡相关=========== */
#chat {
    backdrop-filter: none !important;
}
/* ===========气泡基础和pc端=========== */
    /* 1. 定义气泡本体 */
.mes {
    position: relative;
    padding: 30px 0px 80px 0px !important;
    background-image: url('https://i.postimg.cc/FK43RRFf/16.png') !important;
    background-size: 100% auto !important;
    background-repeat: repeat-y !important;
    background-position: top center !important;
    z-index: auto !important;  
    margin-top: calc(100% / 1.7) !important;   
    margin-bottom: 0px !important;
    padding: 5px;
    border: none !important;
    border-radius: 0 !important; 
    overflow: visible !important;  
}
    /* 2. 顶部背景板 */
.mes::before {
    content: '';
    position: absolute;
    pointer-events: none;
    bottom: 100% !important;
    margin-bottom: -18% !important;
    left: 0;
    right: 0;
    width: 100%;
    aspect-ratio: 1.3 / 1;   
    background-image: url('https://i.postimg.cc/hvbTnbBN/15.png') !important;
    background-color: transparent !important;
    background-size: contain !important;  
    background-repeat: no-repeat;
    background-position: center top !important;
    z-index: 2;
}
    /* 3. 头像定位 */
.mes .mesAvatarWrapper {
    position: absolute !important;
    z-index: auto !important;        
    bottom: 100%;      
    transform: none !important;  
    height: auto;
    aspect-ratio: 1 / 1.6;
}
.mes .avatar {
    width: 100% !important;
    height: 100% !important;
    overflow: hidden;
    position: relative !important;
    z-index: 1 !important;   
}
.mes .avatar img {
    width: 100% !important;
    height: 100% !important;
    object-fit: contain;    
    border: none !important;
}
.mes .mes_block {
    position: relative;
    z-index: 2;
    background: transparent !important;
    overflow: visible !important;
}
    /* 4. AI头像 */
.mes[is_user="false"] .mesAvatarWrapper {
    left: 9%;
    width: 33%;
    margin-bottom: 5px;
    aspect-ratio: 1 / 1.6;   /* 头像比例 */
}
    /* 5. 用户头像 */
.mes[is_user="true"] .mesAvatarWrapper {
    left: 9%;
    width: 33%;
    margin-bottom: 5px;
    aspect-ratio: 1 / 1.6;   /* 头像比例 */
}
    /* 6. 第一条消息头像补偿 */
.mes:first-child .mesAvatarWrapper {
    margin-bottom: 0px !important;   
}
    /* 7. 底部全宽装饰 */
.mes::after {
    content: '';
    position: absolute;
    bottom: -115px;      
    left: 0;
    right: 0;
    width: 100%;
    height: 200px;      
    background-image: url('https://i.postimg.cc/LsrwJfqV/20.png') !important;
    background-size: cover;   
    background-repeat: no-repeat;
    background-position: center;
    pointer-events: none;
    z-index: 3;
    opacity: 1;
}
.mes.last_mes::after {
    display: none;     
}
    /* 8. 名字样式 */
.mes .name_text {
    position: absolute !important; 
    z-index: 9999 !important;
    display: block !important;
    writing-mode: vertical-lr !important;
    -webkit-writing-mode: vertical-lr !important; 
    text-orientation: upright !important;
    -webkit-text-orientation: upright !important; 
    letter-spacing: 2px !important;
    font-weight: bold !important;
    font-size: 1.4em !important;
    color: rgba(58, 79, 70, 1) !important; 
    height: max-content !important;
    width: auto !important;
    top: auto !important; bottom: 100% !important;
    margin-bottom: 30% !important; left: 57.2% !important;
    transform: translate(-50%, 0) rotate(5deg) !important;
}
.mes .name_text * {
    writing-mode: vertical-lr !important; -webkit-writing-mode: vertical-lr !important;
    text-orientation: upright !important; -webkit-text-orientation: upright !important;
    display: inline !important;
}
    /* 9. 日期样式 */
.mes .timestamp {
    position: absolute !important;
    z-index: 9999 !important;
    font-weight: bold !important;
    color: rgba(107, 144, 128, 1) !important;
    font-size: 0.7em !important;
    white-space: nowrap !important;
    top: auto !important;         
    bottom: 100% !important;     
    margin-bottom: 23% !important;    
    left: 76% !important;     
}
    /* 10. pc三元素 */
.mes .mesIDDisplay, .mes .mes_timer, .mes .tokenCounterDisplay {
    position: absolute !important;
    z-index: 9999 !important;
    color: rgba(107, 144, 128, 1) !important;
    font-family: 'STDongGuanTi', sans-serif !important;
    font-size: 11px !important;
    font-weight: bold !important;
    white-space: nowrap !important;
    background-color: transparent !important;
    border: none !important;
    padding: 0 !important;
    width: max-content !important;
    left: 190% !important;
    bottom: auto !important;
    margin: 0 !important;  
    transform: none !important;
}
.mes .mes_timer:empty, .mes .tokenCounterDisplay:empty { display: none !important; } 
    /* 11. PC坐标 */
.mes .mesIDDisplay { top: 11vw !important; }  /* pc楼层 */
.mes .mes_timer { top: 13vw !important; }   /* pc计时 */
.mes .tokenCounterDisplay { top: 15vw !important; }   /* pc字符数 */
    /* 12. 三元素更改文字 */
.mes .mesIDDisplay::before { content: "第"; margin-right: 2px; }
.mes .mesIDDisplay::after { content: "幅"; margin-left: 2px; }
.mes .mes_timer::before { content: "构思"; margin-right: 2px; }
.mes .tokenCounterDisplay::before { content: "笔触"; margin-right: 2px; }
.mes .tokenCounterDisplay::after { content: "抹"; margin-left: 2px; }

/* ===========气泡移动端=========== */
@media (max-width: 800px) {
    /* 1. AI头像 */
    .mes[is_user="false"] .mesAvatarWrapper {
        width: 31vw !important;     /* 宽度 */
        left: 11% !important;        /* 越小越靠左 */
        margin-bottom: 4vw !important;         /* 越小越往下 */
        aspect-ratio: 1 / 1.6 !important;           /* 头像高宽比 */
    }
    /* 2. 用户头像 */
    .mes[is_user="true"] .mesAvatarWrapper {
        width: 31vw !important;        /* 宽度 */
        left: 11% !important;         /* 越小越靠左 */
        margin-bottom: 4vw !important;        /* 越小越往下 */
        aspect-ratio: 1 / 1.6 !important;        /* 头像高宽比 */
    }
    /* 3. 第一条消息头像修正补偿 */
    .mes:first-child .mesAvatarWrapper {
        margin-bottom: 4vw !important; 
    }
    .mes .avatar img {
        object-fit: contain !important;
    }
    /* 4. 最后一条头像调整 */
.mes.last_mes .mesAvatarWrapper {
        width: 38vw !important;      /* 宽度 */
        left: 8% !important;      /* 越小越靠左 */
        margin-bottom: -9vw !important;      /* 越小越往下 */
        aspect-ratio: 1 / 1.6 !important;      /* 头像高宽比 */
    }
    /* 5. 移动端三元素 */
    .mes:not(.last_mes) .mesIDDisplay { top: 22vw !important; }   /* 楼层 */
    .mes:not(.last_mes) .mes_timer { top: 26vw !important; }   /* 计时 */
    .mes:not(.last_mes) .tokenCounterDisplay { top: 30vw !important; }   /* 字符数 */
    .mes .name_text { font-size: 12px !important; margin-bottom: 34vw !important; left: 57.5% !important; }    /* 名字 */
    .mes .timestamp { margin-bottom: 12vw !important; left: 9% !important; }     /* 日期  */
    .mes.last_mes .mesIDDisplay, .mes:last-child .mesIDDisplay { top: 20vw !important; left: 164% !important; }     /* 最后一条消息楼层 */
    .mes.last_mes .mes_timer, .mes:last-child .mes_timer { top: 24vw !important; left: 164% !important; }     /* 最后一条消息计时 */
    .mes.last_mes .tokenCounterDisplay, .mes:last-child .tokenCounterDisplay { top: 28vw !important; left: 164% !important; }       /* 最后一条消息字符数 */
    /* 6. 底部装饰图 */
    .mes::after {
        height: 25vw !important;    
        bottom: -16vw !important;   
    }
}

/* ===========聊天内容区域=========== */
.mes_block {
    display: block;
    max-width: 98%;        
    margin: 0 auto;     
    padding: 0 15px !important;
    box-sizing: border-box !important;
}
.mes_text {
    display: block;
    width: 100%;        
}
.mes .mes_block .mes_text {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
    text-align: justify;
    line-height: 1.5;           /* 行高 */
}
/* 段落首行缩进 */
p {
    text-indent: 2em;
}

/* ===========思维链=========== */
.mes_reasoning {
  background-color: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 5px 10px !important;
  color: rgba(74, 87, 66, 0.9) !important;    
  font-size: 1em !important;
  line-height: 1.5 !important;
}
.mes_reasoning_header_block {
  display: flex !important;
  justify-content: center !important;
  align-items: center !important;
  position: relative !important;    
  width: 100% !important;
  background: transparent !important;
}
.mes_reasoning_header {
  background-image: none !important;       
  background-color: transparent !important;    
  border: 1px dashed rgba(140, 179, 105, 0.8) !important; 
  border-radius: 5px !important;    
  padding: 5px 20px !important;   
  width: fit-content !important;
  display: flex !important;
  justify-content: center !important;
  align-items: center !important;
  cursor: pointer !important;
  transition: all 0.2s ease !important;
}
.mes_reasoning_header_title {
  font-size: 0 !important;     
}
.mes_reasoning_header_title::after {
  content: '𝒮𝓅𝓇𝒾𝓃ℊ 𝒾𝓈 𝒶𝒷ℴ𝓊𝓉 𝓉ℴ 𝒷𝓁ℴℴ𝓂';  
  font-size: 13px !important; 
  color: rgba(107, 144, 128, 0.9) !important; 
  font-family: 'STDongGuanTi', sans-serif !important; 
  letter-spacing: 3px !important;
  visibility: visible !important;
}
.mes_reasoning_arrow,
.mes_reasoning_arrow.fa-chevron-up,
.mes_reasoning_arrow.fa-chevron-down {
  display: none !important;
  visibility: hidden !important;
  opacity: 0 !important;
  width: 0 !important;
  height: 0 !important;
  font-size: 0 !important;
  margin: 0 !important;
}
.mes_reasoning_header_block > *:not(.mes_reasoning_header) {
  position: absolute !important;
  right: 10px !important;    
  top: 50% !important;
  transform: translateY(-50%) !important;    
  display: flex !important;
  gap: 5px !important;
}
/* 思维链与正文间距 */
.mes_reasoning_details {
    margin-top: -64px;
    margin-bottom: 20px !important;   
}

/* ===========世界书相关=========== */
.world_entry_form .world_entry_thin_controls .flex-container.alignitemscenter.wide100p {
    flex-wrap: nowrap !important;
}
/* 标题输入框 */
.world_entry_form .WIEntryTitleAndStatus textarea.text_pole[name="comment"] {
    width: 120px !important;
    min-width: 100px;
}
/* 标题区域 */
.world_entry_form .WIEntryTitleAndStatus {
    flex: 0 0 auto !important;
    margin-right: 5px;
}
/* 右侧控件区域 */
.world_entry_form .WIEnteryHeaderControls {
    flex: 1 1 auto !important;
    flex-wrap: nowrap !important;
    min-width: 0;
    gap: 4px;  
}
.world_entry_form .WIEnteryHeaderControls > div {
    flex-shrink: 1;
    white-space: nowrap;
}
/* 统一宽度 */
.world_entry_form .WIEnteryHeaderControls input[type="number"] {
    width: 70px !important;
}
.world_entry_form .WIEnteryHeaderControls select[name="position"] {
    width: auto;
    min-width: 100px;
}
/* 标签字体 */
.world_entry_form .WIEnteryHeaderControls label {
    font-size: 0.9em;
}
/* 移动端 */
@media (max-width: 600px) {
    .world_entry_form .world_entry_thin_controls .flex-container.alignitemscenter.wide100p {
        flex-wrap: wrap !important;
    }
    .world_entry_form .WIEntryTitleAndStatus {
        flex: 1 1 100% !important;
        margin-right: 0;
        margin-bottom: 3px;
    }
    .world_entry_form .WIEntryTitleAndStatus textarea.text_pole[name="comment"] {
        width: 100% !important;
    }
    .world_entry_form .WIEntryTitleAndStatus select[name="entryStateSelector"] {
        width: auto;
    }
    .world_entry_form .WIEnteryHeaderControls {
        flex: 1 1 100% !important;
        flex-wrap: wrap !important;
        justify-content: flex-start;
        gap: 4px;
    }
    .world_entry_form .WIEnteryHeaderControls > div {
        flex: 0 1 auto;
        margin-right: 6px;
        margin-bottom: 4px;
    }
    .world_entry_form .WIEnteryHeaderControls select[name="position"] {
        min-width: 130px;
    }
    .world_entry_form .WIEnteryHeaderControls input[type="number"] {
        width: 70px !important;
    }
    .world_entry_form .WIEnteryHeaderControls label {
        font-size: 0.85em;
    }
}

/* ===========多选框标签=========== */
li.select2-selection__choice,
li.select2-selection__choice:hover {
    background-color: rgba(107, 144, 128, 0.25) !important; 
    border: 1px solid rgba(107, 144, 128, 0.6) !important;  
    border-radius: 0 !important;      
}
li.select2-selection__choice span.select2-selection__choice__display,
li.select2-selection__choice span.interactable {
    color: rgba(58, 79, 70, 1) !important;  
    background-color: transparent !important; 
}
button.select2-selection__choice__remove {
    background-color: transparent !important;
    color: rgba(107, 144, 128, 1) !important;  
    border: none !important;
    border-right: 1px solid rgba(107, 144, 128, 0.4) !important;  
    border-radius: 0 !important;
}
button.select2-selection__choice__remove:hover {
    background-color: rgba(205, 133, 126, 0.9) !important;  
    color: white !important;   
}

/* ===========全局下拉框=========== */
select option {
    background-color: #EAF1EE !important; 
    color: #3A4F46 !important; 
}

/* ===========下拉框重叠的问题=========== */
#aux_field,
#tag_import_setting {
    margin-top: 4px !important;
}
.flex-container:has(> #aux_field),
.flex-container:has(> #tag_import_setting) {
    margin-bottom: 5px !important;
}

/* ===========各种标题背景=========== */
.title_restorable.standoutHeader,
.margin0.title_restorable,
.standoutHeader,
.text_pole,
.range-block-counter input,
.drawer-content select,
.select2-selection.select2-selection--multiple,
.select2-container .select2-selection--multiple,
.select2-container .select2-selection--single,
.textarea_compact,
h4.title_restorable,
h4,
.inline-drawer-toggle.inline-drawer-header,
.mdHotkeys:not(#send_textarea):not(#send_form *):not(.mes_text),
.height100p.wide100p {
  background: rgba(233, 247, 235, 0.6) !important;    /* 背景 */
  color: var(--SmartThemeBodyColor);
}
.title_restorable.standoutHeader,
.margin0.title_restorable,
.standoutHeader,
.text_pole {
padding: 3px 10px;
}

/* ===========阴影和滤镜=========== */
* {
  box-shadow: none !important;
  text-shadow: none !important;
  filter: none !important;
}

/* ===========小铅笔=========== */
.mes_button {
  font-size: 0.8em;
  background: none;
  border: none;
  box-shadow: none;
}
.mes_button:hover {
  background: none;
}

/* ===========底栏上缝隙=========== */
#form_sheld {
  margin: 0;
}

/* ===========删除/警告按钮=========== */
.red_button, 
.menu_button.red_button, 
.redWarningBG, 
.menu_button.redWarningBG {
    background-color: var(--SmartThemeBlurTintColor) !important;  
    border: 1px solid var(--SmartThemeBorderColor) !important;   
    color: var(--SmartThemeBodyColor) !important;            
    box-shadow: none !important;
}
.red_button:hover, 
.menu_button.red_button:hover, 
.redWarningBG:hover, 
.menu_button.redWarningBG:hover {
    background-color: var(--white30a) !important; 
}
.popup-button-ok,
.menu_button_default,
.popup-button-default {
    background-color: rgba(107, 144, 128, 0.9) !important;    
    color: white !important;
    border: 1px solid rgba(107, 144, 128, 0.9) !important;
    border-radius: 0 !important;    
}
.popup-button-ok:hover,
.menu_button_default:hover,
.popup-button-default:hover {
    background-color: rgba(85, 120, 105, 1) !important; 
}

/* ===========选中角色高亮=========== */
.avatar-container.selected {
    background-color: rgba(213, 230, 216, 0.6) !important; 
    border: 1px solid rgba(107, 144, 128, 0.6) !important;  
}
.avatar-container:not(.selected):hover {
    background-color: rgba(107, 144, 128, 0.1) !important;  
}

/* ===========消息编辑栏=========== */
.mes_edit_buttons .menu_button {
    background-color: transparent !important;
    border: none !important;     
    font-size: 0.9em !important;  
    padding: 4px 4px !important;   
    min-width: 0 !important;
    margin: 0 1px !important;
    color: rgba(107, 144, 128, 0.9) !important; 
}

/* ===========斜体文字=========== */
.mes_text em,
.mes_text i {
    background-image: linear-gradient(
        to top, 
        rgba(239, 163, 39, 0.25) 40%, 
        transparent 40%
    ) !important;
    background-position: bottom !important;
    background-size: 100% 100% !important;
    background-repeat: no-repeat !important;
    padding: 0 3px !important;
    border-radius: 2px !important;     
    font-style: italic !important;
}

/* ===========代码相关=========== */
/* 行内代码 */
code {
    background-color: rgba(249, 168, 38, 0.3) !important;
    color: #4a5742 !important;
    padding: 3px 8px;
    border-radius: 6px !important;
    font-size: 0.9em;
    font-weight: 500;
    border: 2px dashed rgba(140, 179, 105) !important;
}
/* 代码块 */
pre {
    background-color: rgba(249, 168, 38, 0.25) !important;
    color: #4a5742 !important;
    border-radius: 6px !important;
    padding: 2px !important;
    overflow-x: auto;
    border: 2px dashed rgba(140, 179, 105) !important;  /* 浅绿色虚线，透明度0.8 */
}
pre code {
    background-color: transparent !important;
    color: inherit !important;
    padding: 0;
    border: none !important;
}
/* 装饰图片 */
code, pre {
    position: relative;  
    overflow: visible;  
}
/* 代码块图 */
pre::after {
    content: "";
    position: absolute !important;
    top: -7px !important;
    right: -10px !important;
    width: 18px !important;
    height: 18px !important;
    background-image: url('https://i.postimg.cc/RhYMrR65/2.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    pointer-events: none !important;
    z-index: 2 !important;
}
pre code::after {
    content: none !important;
    background-image: none !important;
    display: none !important;
}
/* 行内代码图 */
code::after {
    content: "";
    display: inline-block !important;  
    width: 18px !important;
    height: 18px !important;
    background-image: url('https://i.postimg.cc/RhYMrR65/2.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    vertical-align: middle !important; 
    position: relative !important; 
    top: -10px !important; 
    left: 0px !important; 
    margin-right: -18px !important; 
    pointer-events: none !important;
    z-index: 2 !important;
}

/* ===========删除消息操作=========== */
.mes[is_user], .mes:not([is_user]) {
    position: relative !important;
}
.del_checkbox {
    position: absolute !important;
    left: 50px !important; 
    top: 20px !important;
    z-index: 10 !important;
    width: 22px !important;
    height: 22px !important;
    background-color: rgba(255, 255, 255, 0.8) !important;
    border: 2px solid #e11d48 !important;
}
.del_checkbox::before {
    display: none !important;
}
.del_checkbox:checked ~ .mes_block {
    background-color: rgba(220, 38, 38, 0.5) !important;
    transition: background-color 0.2s ease-in-out !important;
}

/* ===========折叠箭头=========== */
.inline-drawer-icon {
    background-image: none !important;
    width: 1.2em !important;
    height: 1.2em !important;
    display: inline-flex !important;
    align-items: center;
    justify-content: center;
    transition: transform 0.3s ease !important;
}
.inline-drawer-icon::before {
    content: none !important;
}
.inline-drawer-icon::after {
    content: '' !important;
    width: 0 !important;
    height: 0 !important;
    border-style: solid !important;
    border-width: 6px 6px 0 6px !important;
    border-color: rgba(140, 179, 105, 0.9) transparent transparent transparent !important;
}
.inline-drawer-icon.fa-circle-chevron-up,
.inline-drawer-icon.up,
.inline-drawer-icon:not(.down) {
    transform: rotate(180deg) !important;
}

/* ===========面板区域直角化=========== */
/* 1. 直角 */
#left-nav-panel,
#right-nav-panel,
.drawer-content,
#left-nav-panel *,
#right-nav-panel *,
.drawer-content *,
#send_form,
#send_textarea {
    border-radius: 0 !important;
}
/* 2. 保留 */
#left-nav-panel code, #left-nav-panel pre,
#right-nav-panel code, #right-nav-panel pre,
.drawer-content code, .drawer-content pre {
    border-radius: 6px !important;
}

/* ===========正则面板=========== */
/* 1. 正则 */
.regex-script-label {
  width: 90%; /* 正则宽度 */
  border: 1px solid rgba(143, 181, 164) !important; 
  background-color: rgba(189, 226, 205, 0.4) !important; 
  padding: 3px 8px;
  transition: all 0.2s ease;
}
/* 2. 按钮 */
.regex-script-label .menu_button {
  padding: 1px 3px; /* 内边距 (上下, 左右) */
  min-width: 0;
  margin: 0 1px; 
  line-height: 1.2; 
