/* ===========全局复选框=========== */
input[type="checkbox"] {
    -webkit-appearance: none !important;
    appearance: none !important;
    width: 1.3em !important;      
    height: 1.3em !important;
    margin: 0 0 0 0 !important;
    border: none !important;      
    background-color: transparent !important; 
    cursor: pointer !important;
    vertical-align: middle !important;
    outline: none !important;
    position: relative !important;
    top: 6px !important;
    /* 未选中状态 */
    background-image: url("data:image/svg+xml;charset=UTF-8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' stroke='%238CB369' stroke-width='1.5' fill='none' stroke-linecap='round' stroke-linejoin='round'%3E%3Cpath d='M 12 8 A 3.5 3.5 0 1 1 15.8 10.8 A 3.5 3.5 0 1 1 14.4 15.2 A 3.5 3.5 0 1 1 9.6 15.2 A 3.5 3.5 0 1 1 8.2 10.8 A 3.5 3.5 0 1 1 12 8' /%3E%3Ccircle cx='12' cy='12' r='1.5' /%3E%3C/svg%3E") !important;
    background-size: contain !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
    transition: transform 0.2s cubic-bezier(0.175, 0.885, 0.32, 1.275) !important;
}
    /* 选中状态 */
input[type="checkbox"]:checked {
    background-image: url("data:image/svg+xml;charset=UTF-8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='%238CB369'%3E%3Cpath d='M 12 8 A 3.5 3.5 0 1 1 15.8 10.8 A 3.5 3.5 0 1 1 14.4 15.2 A 3.5 3.5 0 1 1 9.6 15.2 A 3.5 3.5 0 1 1 8.2 10.8 A 3.5 3.5 0 1 1 12 8' /%3E%3Ccircle cx='12' cy='12' r='2.5' fill='white' /%3E%3C/svg%3E") !important;
    animation: daisy-pop 0.35s cubic-bezier(0.175, 0.885, 0.32, 1.275) !important;
}
/* 去掉对勾 */
input[type="checkbox"]::before,
input[type="checkbox"]::after,
input[type="checkbox"]:checked::before,
input[type="checkbox"]:checked::after {
    content: none !important;
    display: none !important;
    background-image: none !important;
}
/* 弹跳动画 */
@keyframes daisy-pop {
    0% { transform: scale(0.8); }
    50% { transform: scale(1.15); }
    100% { transform: scale(1); }
}
/* 复选框上下间距 */
#user-settings-block label.checkbox_label {
    margin-bottom: 1px !important;  
    padding-top: 2px !important;
    padding-bottom: 1px !important;
    transition: background-color 0.2s;
}
/* 复原部分 */
.extension-settings input[type="checkbox"],
.extension_container input[type="checkbox"],
#tavern_helper input[type="checkbox"],
#quick-reply-menu-settings input[type="checkbox"],
#qr--settings input[type="checkbox"],
#qr_container input[type="checkbox"] {
    top: 0px !important; }

/* ===========滚动条=========== */
::-webkit-scrollbar {
  width: 0px;     /* 宽度 */
  background: transparent;     
}
::-webkit-scrollbar-track {
  background: transparent;    
  border: none;      
  box-shadow: none;       
}
::-webkit-scrollbar-thumb {
  background: linear-gradient(to bottom, rgba(240, 247, 233, 1), rgba(180, 210, 150, 1));  
  border-radius: 3px !important;      
  border: none;        
}
::-webkit-scrollbar-corner {
  background: transparent;    
}

/* ===========拉条=========== */
input[type="range"] {
    -webkit-appearance: none;    
    appearance: none;      
    width: 100%;      
    background: transparent !important;  
    border: none !important;    
    box-shadow: none !important;    
    outline: none;      
}

/* Chrome/Safari 轨道 */
input[type="range"]::-webkit-slider-runnable-track {
    width: 100%;        
    height: 3px;    /* 轨道高度 */
    background: rgba(140, 179, 105, 0.8);  
}

/* Chrome/Safari 滑块 */
input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none;    
    appearance: none;
    width: 20px;   
    height: 20px;    
    background: url('https://i.postimg.cc/4d40V2sv/3.png') no-repeat center / contain;  
    border: none;       
    box-shadow: none;    
    cursor: pointer;    
    margin-top: -9px;    /* 垂直偏移 */
}

/* Firefox 轨道 */
input[type="range"]::-moz-range-track {
    width: 100%;
    height: 3px;     /* 轨道高度 */
    background: rgba(140, 179, 105, 0.7); 
    border: none;            
    box-shadow: none;       
}

/* Firefox 滑块 */
input[type="range"]::-moz-range-thumb {
    width: 20px;      
    height: 20px;    
    background: url('https://i.postimg.cc/4d40V2sv/3.png') no-repeat center / contain; 
    border: none;      
    box-shadow: none;       
    cursor: pointer;       
}

/* 数字输入框 */
input.neo-range-input,
input[data-for] {
    background-color: transparent !important;      
    border-width: 0 2px 2px 2px;     
    border-style: dashed;    
    border-color: rgba(140, 179, 105, 0.8);    
    color: inherit;         
}
